export interface PDFSourceDocument {id:string;label:string;pageCount:number;unavailableReason?:string}
export interface ExtractMergeSplitDialogProps extends ScopedControlProps {
 open:boolean;mode:'extract'|'merge'|'split';sources:readonly PDFSourceDocument[];selectedSourceId:string|null;
 onChooseSources:(signal?:AbortSignal)=>unknown;onSelectSource:(id:string)=>void;
 onApply:(request:{mode:'extract'|'merge'|'split';sources:readonly string[];selectedSourceId:string;pages:readonly number[]},signal?:AbortSignal)=>unknown;onClose:()=>void;unstyled?:boolean;
}
/** Native modal review of source order and page selection; host retains file/security scopes and PDF transactions. */
export function ExtractMergeSplitDialog({scope='pdf-page-operation',revision=0,...props}:ExtractMergeSplitDialogProps){
 const {open,mode,sources,selectedSourceId,onChooseSources:_choose,onSelectSource:_select,onApply:_apply,onClose,unstyled=false,disabledReason}=props;
 if(sources.length>256||new Set(sources.map(s=>s.id)).size!==sources.length||sources.some(s=>!s.id.trim()||s.id.length>256||!s.label.trim()||s.label.length>1024||!Number.isSafeInteger(s.pageCount)||s.pageCount<1||s.pageCount>100000)||!['extract','merge','split'].includes(mode))throw new RangeError('Invalid PDF page operation');
 const owner=JSON.stringify([...controlIdentity(scope,revision),mode,open,disabledReason]),guard=useScopedControl(owner,props,!open||disabledReason!==undefined),off=guard.pending||disabledReason!==undefined;
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore();const store=local.current,s=useStore(store,v=>v),source=sources.find(d=>d.id===selectedSourceId),order=s.order.length?s.order.filter(id=>sources.some(d=>d.id===id)).concat(sources.map(d=>d.id).filter(id=>!s.order.includes(id))):sources.map(d=>d.id);
 useLayoutEffect(()=>{store.setState({range:'1',order:[]});},[owner]);
 useLayoutEffect(()=>{store.setState({range:'1'});},[selectedSourceId]);
 const close=()=>{if(guard.cancel())onClose();};
 return <Modal visible={open} transparent animationType="none" onRequestClose={close}><View style={{flex:1,justifyContent:'center',padding:space[4]}} {...{className:unstyled?undefined:'bg-text/25'}}><View accessibilityViewIsModal accessibilityLabel={mode+' PDF pages'} style={{gap:space[2],padding:space[4],maxHeight:'90%'}} {...{className:unstyled?undefined:'bg-surface-raised border border-border rounded-control'}}><Text accessibilityRole="header" {...{className:unstyled?undefined:'text-text'}}>{mode==='merge'?'Merge PDF sources':mode==='extract'?'Extract PDF pages':'Split PDF pages'}</Text><Button title="Choose PDF source documents" disabled={off} unstyled={unstyled} onPress={()=>guard.run('choose',(h,s)=>h.onChooseSources(s))}/>
 <FlatList data={order} keyExtractor={id=>id} initialNumToRender={5} windowSize={5} style={{maxHeight:280}} extraData={[sources,selectedSourceId,off]} renderItem={({item,index})=>{const d=sources.find(s=>s.id===item)!;return <View style={{gap:space[1.5],paddingVertical:space[1.5]}}><Button title={`${index+1}. ${d.label} · ${d.pageCount} pages`} accessibilityState={{selected:d.id===selectedSourceId}} disabled={off||d.unavailableReason!==undefined} accessibilityHint={d.unavailableReason} unstyled={unstyled} onPress={()=>guard.current()?.onSelectSource(d.id)}/>{mode==='merge'?<Button title="Move source earlier" variant="secondary" disabled={off||index===0} unstyled={unstyled} onPress={()=>{const next=[...order];[next[index-1],next[index]]=[next[index]!,next[index-1]!];store.setState({order:next});}}/>:null}</View>;}}/>
 {mode!=='merge'?<><Text {...{className:unstyled?undefined:'text-text'}}>Pages from {source?.label??'selected source'} (for example 1-3, 8)</Text><TextInput accessibilityLabel="PDF page ranges" value={s.range} maxLength={8192} editable={!off} onChangeText={range=>store.setState({range})} style={{minHeight:size.touch,padding:space[2]}} {...{className:unstyled?undefined:'text-text border border-border rounded-control'}}/></>:null}
 <Button title={mode==='merge'?'Merge reviewed source order':mode==='extract'?'Extract reviewed pages':'Split reviewed pages'} disabled={off||(mode==='merge'?sources.length<2||sources.some(s=>s.unavailableReason!==undefined):!source||source.unavailableReason!==undefined)} unstyled={unstyled} onPress={()=>guard.run('apply',(h,signal)=>{const selected=h.sources.find(d=>d.id===h.selectedSourceId)??(h.mode==='merge'?h.sources[0]:undefined);if(!selected)throw new Error('Select a PDF source');if(selected.unavailableReason!==undefined||h.mode==='merge'&&order.some(id=>!h.sources.some(d=>d.id===id&&d.unavailableReason===undefined)))throw new Error('PDF source availability changed');return h.onApply({mode:h.mode,sources:h.mode==='merge'?order:[selected.id],selectedSourceId:selected.id,pages:h.mode==='merge'?[]:parsePDFPageRange(store.getState().range,selected.pageCount)},signal);})}/><Button title="Cancel PDF page operation" variant="secondary" unstyled={unstyled} onPress={close}/><ErrorMessage message={guard.error??disabledReason} unstyled={unstyled}/></View></View></Modal>;
}
function makeStore(){return createStore(()=>({range:'1',order:[] as string[]}));}

export interface PDFPageDescriptor {id:string;label:string;width:number;height:number;rotation:0|90|180|270;canModify:boolean;groupId?:string}
export type PDFPageLayout='single'|'continuous'|'two-up'|'facing';
/** Top-left page coordinates after the host has applied crop/rotation mapping. */
export interface PDFRect {x:number;y:number;width:number;height:number}
export function validatePDFPages(pages:readonly PDFPageDescriptor[]):void{
 if(pages.length>100000||new Set(pages.map(p=>p.id)).size!==pages.length||pages.some(p=>!p.id.trim()||p.id.length>256||!p.label.trim()||p.label.length>1024||![p.width,p.height].every(n=>Number.isFinite(n)&&n>=1&&n<=14400)||![0,90,180,270].includes(p.rotation)))throw new RangeError('Invalid PDF page descriptors');
}
export function validatePDFRect(rect:PDFRect):void{if(![rect.x,rect.y,rect.width,rect.height].every(Number.isFinite)||rect.width<0||rect.height<0)throw new RangeError('Invalid PDF rectangle');}
/** One-based ranges such as 1-3, 8, 10; bounded selection metadata, not PDF processing. */
export function parsePDFPageRange(text:string,pageCount:number):number[]{
 if(!Number.isSafeInteger(pageCount)||pageCount<1||pageCount>100000||text.length>8192)throw new RangeError('Invalid PDF page range');const pages=new Set<number>();
 for(const item of text.split(',')){const match=/^\s*(\d+)\s*(?:-\s*(\d+)\s*)?$/.exec(item);if(!match)throw new Error('Use page numbers and ranges such as 1-3, 8');const a=Number(match[1]),b=Number(match[2]??match[1]);if(!Number.isSafeInteger(a)||!Number.isSafeInteger(b)||a<1||b<a||b>pageCount)throw new Error('Page range is outside this document');for(let n=a;n<=b;n++)pages.add(n-1);}
 return [...pages].sort((a,b)=>a-b);
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

